#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos;
    int cantidad_entrada{0};
    std::cin >> cantidad_entrada;
    for (int entrada{0}; entrada < cantidad_entrada; ++entrada) {
        int dato{0};
        std::cin >> dato;
        datos.push_back(dato);
    }
    int total = 0;
    std::vector<int> elegidos;
    for (int valor : datos) {
        total += valor;
        if (valor >= 4) {
            elegidos.push_back(valor);
        }
    }
    std::cout << "Total: " << total << "\n";
    std::cout << "Elegidos: " << elegidos.size() << "\nValores:";
    for (int valor : elegidos) {
        std::cout << valor << ";";
    }
    return 0;
}
